import { Component, OnInit } from '@angular/core';
import { QrService } from '../services/qr.service';
import { IQrList } from '../services/qr.interface';

@Component({
  selector: 'app-qr-list',
  templateUrl: './qr-list.component.html',
  styleUrls: ['./qr-list.component.scss'],
})
export class QrListComponent implements OnInit {
  qrList: Array<IQrList> = [];
  constructor(private qrService: QrService) {}

  ngOnInit(): void {
    this.getQrList();
  }

  getQrList(): void {
    this.qrService.getQrList().subscribe((qrs) => {
      this.qrList = qrs;
    });
  }
}
<div class="container">
  <div class="row">
    <div *ngFor="let qr of qrList" class="col-12 col-md-3">
      <qrcode
        [qrdata]="qr.code"
        [width]="256"
        [errorCorrectionLevel]="'M'"
      ></qrcode>
      <p class="text-center">{{ qr.status.toUpperCase() }}</p>
    </div>
  </div>
</div>
